import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Spell variants and glyphs","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/magic/variants-and-glyphs.md","filePath":"en/game-design/magic/variants-and-glyphs.md"}'),n={name:"en/game-design/magic/variants-and-glyphs.md"};function o(s,e,d,l,c,m){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="spell-variants-and-glyphs" tabindex="-1">Spell variants and glyphs <a class="header-anchor" href="#spell-variants-and-glyphs" aria-label="Permalink to &quot;Spell variants and glyphs&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; listed decisions remain Unresolved. Existing Accepted foundations retain their scope. <strong>Implementation:</strong> no Batch 04 gameplay implementation established. <strong>Availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation reconciliation only, not runtime validation. <strong>Reviewed:</strong> 2026-10-09 against Batch 04 and <a href="/Syrolands-Public/en/game-design/magic.html">earlier magic design</a>.</p><p><a href="/Syrolands-Public/en/guide/magic/variants-and-glyphs.html">Player guide</a> · <a href="/Syrolands-Public/en/game-design/magic.html">Magic overview</a> · <a href="/Syrolands-Public/en/game-design/magic/status-and-open-questions.html">Status and open questions</a></p><h2 id="bounded-learned-modification" tabindex="-1">Bounded learned modification <a class="header-anchor" href="#bounded-learned-modification" aria-label="Permalink to &quot;Bounded learned modification&quot;">​</a></h2><p>Known Core Patterns can accept compatible learned modifiers/glyphs. Every modifier must trade a benefit for a cost or constraint; pure upgrade stacking is not the goal. Compatibility depends on structure/family rather than assuming that every modifier works on every spell.</p><table tabindex="0"><thead><tr><th>Family</th><th>Illustrative changes</th><th>Trade-off direction to evaluate</th></tr></thead><tbody><tr><td>Shape</td><td>Compressed projectile, wider burst, chain behavior, delayed detonation</td><td>Area, intensity, complexity or timing constraints</td></tr><tr><td>Delivery</td><td>Faster travel, slower/heavier impact, arcing, ground trigger</td><td>Travel/impact balance, cost or exposure</td></tr><tr><td>Targeting</td><td>Easier general target, difficult limb focus, area placement</td><td>Precision versus Difficulty, preparation or resources</td></tr><tr><td>Effect</td><td>Burn versus direct damage, local trauma, disruption, armor heating, utility emphasis</td><td>Give up another effect or pay a meaningful cost</td></tr><tr><td>Cost / Stability</td><td>Mana, cast duration, Concentration, reagents, interruption resistance</td><td>Lower cost or higher stability cannot be free</td></tr></tbody></table><p>These are families and examples, not a roster of implemented effects. Core Pattern plus a limited major/minor modifier budget bounds combinatorics for balance, readability, counterplay, visual clarity and implementation feasibility. Advanced patterns may support different budgets; counts and complexity limits remain Unresolved.</p><h2 id="horizontal-spell-augmentation" tabindex="-1">Horizontal spell augmentation <a class="header-anchor" href="#horizontal-spell-augmentation" aria-label="Permalink to &quot;Horizontal spell augmentation&quot;">​</a></h2><p>A scribe who knows a spell may produce an augmentation for it. The recipient must already permanently know the underlying spell to apply an augmentation; possessing a modifier is not spell acquisition.</p><table tabindex="0"><thead><tr><th>Illustrative modifier</th><th>Possible benefit</th><th>Possible trade-off</th></tr></thead><tbody><tr><td>Wall of Fire + Glyph of Persistence</td><td>Longer duration</td><td>More mana</td></tr><tr><td>Glyph of Compression</td><td>Greater intensity</td><td>Smaller area</td></tr><tr><td>Glyph of Reach</td><td>Longer range</td><td>Higher Difficulty</td></tr><tr><td>Glyph of Stability</td><td>Lower effective Difficulty</td><td>A cost/constraint still to define</td></tr><tr><td>Focused Fireball</td><td>Stronger center</td><td>Smaller area</td></tr><tr><td>Volatile Fireball</td><td>Wider area</td><td>Instability, expense or Difficulty</td></tr><tr><td>Efficient Fireball</td><td>Less mana</td><td>Reduced power</td></tr><tr><td>Piercing Fireball</td><td>Better against particular defenses</td><td>Higher Difficulty</td></tr></tbody></table><p>These examples are tactical alternatives, not an approved spell list or an “Improved Fireball I/II/III” ladder. Benefits with unresolved costs are not free upgrades.</p><h2 id="prepared-configurations-and-crafted-grimoires" tabindex="-1">Prepared configurations and crafted grimoires <a class="header-anchor" href="#prepared-configurations-and-crafted-grimoires" aria-label="Permalink to &quot;Prepared configurations and crafted grimoires&quot;">​</a></h2><p>A possible later system limits active modifier configurations while leaving learned knowledge permanent. Incinerate prepared with Stable Channel and Focused Flame illustrates the distinction; neither two slots nor these modifiers are final.</p><p>Scholar&#39;s Spellbook, Battle Grimoire, Ritual Codex, Forbidden Tome and Masterwork Grimoire are candidate book identities. They alter preparation/configuration, not permanent spell ownership. Exact slots, switching rules, modifier ownership/consumption and prepared versus always-available access remain unresolved.</p><p>An institution might teach “Incinerate: White Flame Formula” after another teaches Incinerate. It could be a rare augmentation, execution method or specialized formula rather than a separate spell. This keeps exploration relevant after base learning.</p><h2 id="variants-in-active-memory" tabindex="-1">Variants in Active Memory <a class="header-anchor" href="#variants-in-active-memory" aria-label="Permalink to &quot;Variants in Active Memory&quot;">​</a></h2><p>Memorizing Fireball need not prepare every modified Fireball. A Compression variant might have a separate memory complexity cost; alternatively reconstructing the modifier might add cast or Concentration cost. These are unresolved alternatives, not two simultaneously selected rules. <a href="/Syrolands-Public/en/game-design/magic/memory-and-familiarity.html">Active Memory</a> owns preparation and reference; familiarity with a core does not automatically prove mastery of every variant.</p><p>A modifier can add/substitute reagents or catalysts and increase material cost, subject to the <a href="/Syrolands-Public/en/game-design/magic/spellbooks-scrolls-and-reagents.html">material rules</a>. <a href="/Syrolands-Public/en/game-design/professions/inscription.html">Inscription</a> may encode stable variants. The <a href="/Syrolands-Public/en/game-design/magic/presentation.html">visual grammar</a> must communicate meaningful variation without requiring a bespoke asset for every combination.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Major/minor counts, per-pattern compatibility, stacking/conflicts, variant complexity costs, ownership and consumption of modifiers, improvised versus separately memorized variants, craft prerequisites and trade-off strength. No universal compatibility table or final slots are selected.</p>',20)])])}const u=t(n,[["render",o]]);export{h as __pageData,u as default};
